-- FidelityEMatrix/EMatrix_Terrain.lua
-- The scene rebuilt from the map data: every tree, rock, fence and lamp placement near the
-- player (EMatrix_Data, generated by tools/ematrix_mapdata.mjs from the game's own tiles) is
-- projected through the camera (EMatrix_Math.BuildCamera) and drawn as a Model frame at its
-- screen position, with the same depth parallax and anaglyph pairs as the unit actors of
-- EMatrix_World.lua.
--
-- Honest limits: the ground surface itself cannot be drawn (addons draw textures and models, not
-- meshes); the heightmap only places things on the real ground. Buildings (WMOs) are counted
-- but not drawn: a Model frame loads M2 models only. The client exposes no camera pitch and
-- refuses to measure nameplates ("Can't measure restricted regions"), so the saved pitch is
-- used: tune it with /fide terrain pitch <deg> while looking at a tree until the copy stands
-- on it. The vertical field of view (/fide terrain fov) is calibrated the same way; neither can
-- be checked headless.

local ADDON_NAME, ns = ...
local Math = ns.Math or _G.EMatrix_Math
local Terrain = {}
ns.Terrain = Terrain

local MAX_PROPS = 24           -- model frames in the pool (each is a draw of a full model)
local SCAN_INTERVAL = 0.25     -- seconds between placement scans
local RADIUS = 70              -- yards: placements beyond this are not drawn
local MIN_PX = 14              -- smaller projected props are skipped
local MAX_PX_FACTOR = 2.0      -- a prop is never drawn taller than this many screen heights
local MIN_DEPTH = 1.0          -- yards down the view axis: nearer than this the projection explodes
local SCREEN_MARGIN = 200      -- pixels beyond the screen edge a prop may still be drawn
local RETRY_AFTER = 8          -- seconds before a model that failed to load is tried again
local PX_GAIN = 60             -- parallax pixels per unit of ParallaxShift (as the window)
local STEREO_REF_Z = 0.5
local LEVEL_MIN, LEVEL_SPAN = 2, 50 -- frame levels: the nearest prop draws on top of farther ones

-- Nominal model heights in yards by path keyword, until bounding boxes are read from the models
local HEIGHT_RULES = {
    { "canopy", 16 }, { "tree", 14 }, { "bush", 2.5 }, { "shrub", 2 }, { "rock", 3 }, { "stone", 2.5 },
    { "fence", 1.5 }, { "lamp", 4 }, { "post", 2 }, { "crate", 1 }, { "barrel", 1.2 }, { "jar", 0.7 },
}
local HEIGHT_DEFAULT = 1.5
-- Trees and canopies are wider than tall on screen; a frame 0.8 as wide as it is tall clipped the
-- far canopies into blocks (the owner's eighth report, 12:46 local), so their frames are wider.
-- Whether the width changes how the camera frames the model's height is open: the tree's top reach
-- read 1.34 frame heights in the ninth report's wide frame against about 1.6 in the narrow frames, so
-- the ledger keys every fit reading on its frame's aspect (a reading in the other aspect does not count).
local ASPECT_RULES = { { "canopy", 1.5 }, { "tree", 1.5 } }
local ASPECT_DEFAULT = 0.8
local function AspectFor(path)
    local p = (path or ""):lower()
    for _, rule in ipairs(ASPECT_RULES) do
        if p:find(rule[1], 1, true) then return rule[2] end
    end
    return ASPECT_DEFAULT
end
local function NominalHeight(path)
    local p = (path or ""):lower()
    for _, rule in ipairs(HEIGHT_RULES) do
        if p:find(rule[1], 1, true) then return rule[2] end
    end
    return HEIGHT_DEFAULT
end

local MAP_BY_INSTANCE = { [0] = "azeroth", [1] = "kalimdor", [530] = "expansion01", [571] = "northrend" }

--- The data family for this client: 1.x (WoW Forever, Classic Era) = "vanilla", 2.x = "tbc".
--- Each family's data is generated from that family's own build (model ids differ between them).
--- Any other client (Wrath, Cataclysm, retail) is "unsupported": it has no map data here, so the
--- overlay draws nothing rather than another family's placements at the wrong places.
function Terrain.Family()
    local toc = GetBuildInfo and select(4, GetBuildInfo()) or 0
    toc = tonumber(toc) or 0
    if toc >= 10000 and toc < 20000 then return "vanilla" end
    if toc >= 20000 and toc < 30000 then return "tbc" end
    return "unsupported"
end

function Terrain.Data()
    return EMatrix_Data and EMatrix_Data[Terrain.Family()] or nil
end

function Terrain.BuildLabel()
    local fam = Terrain.Family()
    if fam == "unsupported" then
        local toc = GetBuildInfo and select(4, GetBuildInfo()) or "?"
        return "unsupported client family (interface " .. tostring(toc) .. "): map data exists for 1.x and 2.x clients only"
    end
    local b = EMatrix_Data and EMatrix_Data.builds and EMatrix_Data.builds[fam]
    return fam .. (b and (" (data from build " .. tostring(b.build) .. ", " .. tostring(b.product) .. ")") or " (no data for this client family)")
end

--- Tiles and placements in this client's data set (for the login line and the status).
function Terrain.DataStats()
    local data = Terrain.Data()
    local tiles, placements, buildings = 0, 0, 0
    if data then
        for _, tile in pairs(data) do
            if type(tile) == "table" and tile.doodads then
                tiles = tiles + 1
                placements = placements + #tile.doodads
                buildings = buildings + #(tile.wmos or {})
            end
        end
    end
    return tiles, placements, buildings
end
local TILE = 533.33333

local overlay, backdropTex
local pool = {}                -- { mono, left, right, key, entry, height, used }
local enabled = false
local suspended = nil          -- reason text while the overlay stopped itself after errors (saved choice untouched)
local scanAge = 0
local clock = 0                -- seconds the overlay has run (dt summed), for the retry timer
local candidates = {}          -- reused scratch of { e, d2, key }
local tilesScratch = {}        -- reused: the player's tile and its existing neighbours
local failedAt = {}            -- model key -> clock when its load last failed (retried after RETRY_AFTER)
local DEFAULTS = { terrainOverlay = true, terrainLoader = "path", terrainFovY = 1.0, terrainPitch = 0.35, terrainBackdrop = "none" }

local function Cfg(k)
    local v = FidelityEMatrix_Config and FidelityEMatrix_Config[k]
    if v == nil then v = DEFAULTS[k] end
    if v == nil then v = ns.Cfg(k) end
    return v
end

--- Where a camera number comes from. The client gives no pitch and no field of view to read, so no
--- camera number here is a reading: it is the saved default until the owner sets it himself.
local function CameraKind(key)
    local v = FidelityEMatrix_Config and FidelityEMatrix_Config[key]
    if v == nil then return "(saved default, not measured)" end
    return "(your setting, not measured)"
end

-- ---------------------------------------------------------------------------
-- Data access
-- ---------------------------------------------------------------------------
function Terrain.TileFor(mapName, x, y)
    local row = math.floor(32 - x / TILE)
    local col = math.floor(32 - y / TILE)
    local data = Terrain.Data()
    return col, row, data and data[mapName .. ":" .. col .. ":" .. row] or nil
end

--- The player's own tile (or nil) and the list of existing tiles in the 3x3 block around it, the
--- own tile first, so placements just across a tile border are drawn too.
function Terrain.TilesAround(mapName, x, y)
    local col, row, own = Terrain.TileFor(mapName, x, y)
    for i = #tilesScratch, 1, -1 do tilesScratch[i] = nil end
    local data = Terrain.Data()
    if not data then return own, tilesScratch, col, row end
    if own then tilesScratch[1] = own end
    for dc = -1, 1 do
        for dr = -1, 1 do
            if dc ~= 0 or dr ~= 0 then
                local t = data[mapName .. ":" .. (col + dc) .. ":" .. (row + dr)]
                if t then tilesScratch[#tilesScratch + 1] = t end
            end
        end
    end
    return own, tilesScratch, col, row
end

--- Ground height at world (x, y) from a tile's 129x129 grid (bilinear), or nil outside it.
function Terrain.GroundHeight(tile, x, y)
    if not tile then return nil end
    local fj = (tile.originX - x) / tile.unit
    local fk = (tile.originY - y) / tile.unit
    if fj < 0 or fk < 0 or fj > 128 or fk > 128 then return nil end
    local j, k = math.floor(fj), math.floor(fk)
    if j == 128 then j = 127 end
    if k == 128 then k = 127 end
    local tj, tk = fj - j, fk - k
    local H = tile.heights
    local function h(jj, kk) return H[jj * 129 + kk + 1] * 0.1 end
    local top = h(j, k) * (1 - tk) + h(j, k + 1) * tk
    local bottom = h(j + 1, k) * (1 - tk) + h(j + 1, k + 1) * tk
    return top * (1 - tj) + bottom * tj
end

-- ---------------------------------------------------------------------------
-- Player state and camera
-- ---------------------------------------------------------------------------
local lastCam

function Terrain.PlayerState()
    if not UnitPosition then return nil end
    -- UnitPosition returns the NORTH-SOUTH coordinate first (the map data's x), then the west-east
    -- one (its y). Measured by the owner's probe on 04 Nov 2026: with the old swapped read it
    -- printed "pos -97.6, -8763.0 ... tile azeroth:48:32 MISSING" at the Northshire Abbey door,
    -- which is tile 32:48. The old comment cited the wiki the other way round, and the headless
    -- stub had copied that belief, so every test agreed with the mistake.
    local ux, uy, _, instanceID = UnitPosition("player")
    if not ux or not uy then return nil end
    local mapName = MAP_BY_INSTANCE[instanceID or 0]
    if not mapName then return nil end
    local facing = GetPlayerFacing and GetPlayerFacing() or 0
    local zoom = GetCameraZoom and GetCameraZoom() or 8
    return { x = ux, y = uy, instanceID = instanceID or 0, mapName = mapName, facing = facing, zoom = zoom }
end

--- The camera from the player's state and the saved pitch (the client gives no pitch and no
--- measurable nameplate to solve it from).
function Terrain.BuildCamera(ps, groundZ)
    local sw, sh = GetScreenWidth() or 1920, GetScreenHeight() or 1080
    local pitch = Cfg("terrainPitch")
    local cam = Math.BuildCamera(ps.x, ps.y, groundZ or 0, ps.facing, ps.zoom, pitch, Cfg("terrainFovY"), sw, sh)
    lastCam = cam
    return cam, pitch
end

-- ---------------------------------------------------------------------------
-- Pool
-- ---------------------------------------------------------------------------
-- The frame kind every prop is drawn on. The owner's third report (v1.8.1, 10:23 local,
-- reports/20261104-1024) settled it: on Burning Crusade Classic 2.5.6 a plain Model frame draws
-- nothing an addon loads by path (the bush, the client's own question-mark model, at any strata,
-- camera or scale), while a PlayerModel frame and a DressUpModel frame draw the same file at the
-- same place. So props are PlayerModel frames first, DressUpModel second, Model last.
local FRAME_ORDER = { "PlayerModel", "DressUpModel", "Model" }
local propFrameKind = nil
local function NewModel(name)
    local m
    for _, kind in ipairs(FRAME_ORDER) do
        local ok, f = pcall(CreateFrame, kind, name, overlay)
        if ok and f then m = f; propFrameKind = propFrameKind or kind; break end
    end
    if not m then return nil end
    m:SetFrameLevel(LEVEL_MIN)
    m.__ematrixLevel = LEVEL_MIN
    m:EnableMouse(false)
    m:Hide()
    return m
end

local function GetSlot(i)
    local s = pool[i]
    if s then return s end
    s = { used = false, key = nil }
    s.mono = NewModel("FidelityEMatrix_Prop" .. i)
    s.left = NewModel("FidelityEMatrix_PropL" .. i)
    s.right = NewModel("FidelityEMatrix_PropR" .. i)
    pool[i] = s
    return s
end

local function HideModels(s)
    if s.mono then s.mono:Hide() end
    if s.left then s.left:Hide() end
    if s.right then s.right:Hide() end
    s.drawH = nil -- nothing drawn: the shutter record says so
end

--- Frees a slot and hides whatever it showed: a slot that is not in use never keeps a picture.
local function ReleaseSlot(s)
    s.used = false; s.key = nil; s.entry = nil
    HideModels(s)
end

-- Classic takes a path; newer engines also take a FileDataID. A SetModel call can succeed
-- without loading anything, so each attempt is checked with GetModelFileID where the client has
-- it; the order is path.m2, id, path.mdx (/fide terrain loader id puts the id first).
local loadStats = { ok = 0, failed = 0, lastFailure = nil, lastWin = nil }
Terrain.loadStats = loadStats

local function Loaded(model)
    if type(model.GetModelFileID) ~= "function" then return true end -- no way to check: trust the call
    local ok, id = pcall(model.GetModelFileID, model)
    return ok and type(id) == "number" and id > 0
end

--- Puts a loaded model where a Model frame can see it: at its origin, facing forward, scale 1.
--- Classic has no SetDefaultModelPosition, so the position is set by hand (CLAUDE.md section 1).
--- No SetCamera here: every prop had SetCamera(0) from v1.6 to v1.7.9 and none was ever visible
--- on the owner's client, including the client's own question-mark model (the 09:35 report), and a
--- doodad file has no camera 0 to select. The test's "cam 0" variant puts the call back on purpose.
-- The camera factor k at which each measured file fills its PlayerModel frame top to bottom, so the
-- frame's projected height is the model's and its base sits at the frame's bottom, where the prop's
-- projected foot is anchored. Every value answers to readings in docs/rungs/ledger.json: the test
-- tools/rung-ledger.test.mjs fails for a value with no reading behind it, and FIT_STATUS carries the
-- ledger's verdict on each (packages/triad-369/src/rung_ledger.mjs decides it).
-- What the readings show (council round 2026-11-04-rungs: the director's second reading of all 35
-- camera-distance fit shots, on crops ticked every 5% of the frame, the bush and tree tops corrected
-- after the round's review re-read them brightened): the frame centres the model's bounds on its
-- mid-line and draws it at 1/k, so a file reaches a fixed distance above and below the mid-line at
-- x1 (the barrel's five readings, x0.6 to x3, agree within 0.025). The proposal is twice the larger
-- reach, the smallest k at which nothing is clipped. The barrel filled 0.83 of its frame at x0.6 (now
-- x0.51); the crate filled 0.80 at x0.42 with its planks past both side edges (now x0.37; a frame
-- about 1.85 as wide as tall would hold it); canopy04 overflowed at x2.8 (a trial at x5.6). At x2 the
-- bush's twigs reach 0.10 to 0.12 below the frame's top and its stems run to the bottom edge: within
-- the readings' precision of the tolerance, so undecided; its reaches (up 0.78, down at least 1.0)
-- mean no k alone fills its frame, which needs a vertical offset. The jar's and the tree's bases were
-- hidden behind the world overlay's copy of the player. None is confirmed: the next report's twins
-- read both edges of every model.
local REF_HEIGHT = 2.5
local FIT_BY_FILE = { elwynnbush09 = 2.0, elwynntreemid01 = 2.8, westfallbarrel01 = 0.51, jar01 = 0.37, westfallcrate = 0.37, elwynntreecanopy04 = 5.6 }
-- The ledger's verdict on each value above (holds, fitted, fails, contested), the report it cites, and
-- for a fitted value where the value came from: "estimated" (the evaluator's proposal from the
-- readings), "read" (readings at this value exist but none could decide) or "trial" (a step after
-- an overflow, not an estimate).
local FIT_STATUS = {
    elwynnbush09 = { "fitted", "20261104-1247", "read" },
    elwynntreemid01 = { "fitted", "20261104-1321", "read" },
    westfallbarrel01 = { "fitted", "20261104-1247", "estimated" },
    jar01 = { "fitted", "20261104-1321", "read" },
    westfallcrate = { "fitted", "20261104-1321", "estimated" },
    elwynntreecanopy04 = { "fitted", "20261104-1321", "trial" },
}
-- (nominal height, the fit in use), ascending: an unmeasured file takes an interpolation between them,
-- a guess. canopy04's x5.6 is a trial step after an overflow, not a fit, so it steers no other canopy.
local FIT_KNOTS = { { 0.7, 0.37 }, { 1.0, 0.37 }, { 1.2, 0.51 }, { 2.5, 2.0 }, { 14, 2.8 } }
local function FileKey(path)
    local p = tostring(path or ""):lower():gsub("\\", "/")
    return p:match("([^/]+)%.%w+$") or p:match("([^/]+)$") or p
end
--- The owner's own fits, saved by /fide terrain test fit <k> on the picked prop (SavedVariables).
local function OwnerFit(key)
    local t = FidelityEMatrix_Config and FidelityEMatrix_Config.propFit
    local v = t and key and tonumber(t[key])
    return v and v > 0 and v or nil
end
local function InterpolatedFit(h)
    local first, last = FIT_KNOTS[1], FIT_KNOTS[#FIT_KNOTS]
    if h <= first[1] then return first[2] end
    if h >= last[1] then return last[2] end
    for i = 2, #FIT_KNOTS do
        local a, b = FIT_KNOTS[i - 1], FIT_KNOTS[i]
        if h <= b[1] then return a[2] + (b[2] - a[2]) * (h - a[1]) / (b[1] - a[1]) end
    end
    return last[2]
end
local function CameraDistanceFor(heightYd, path)
    local key = path and FileKey(path) or nil
    local known = key and (OwnerFit(key) or FIT_BY_FILE[key]) or nil
    if known then return math.min(math.max(known, 0.25), 16.0) end
    local h = tonumber(heightYd) or REF_HEIGHT
    if h <= 0 then h = REF_HEIGHT end
    return math.min(math.max(InterpolatedFit(h), 0.25), 16.0)
end
local STATUS_TEXT = {
    holds = "a fit confirmed in report %s",
    estimated = "a fit estimated from report %s, not confirmed",
    read = "a fit read at this value in report %s, undecided",
    trial = "a trial value after report %s (it overflowed there), not a fit yet",
    fails = "a fit that failed in report %s, to be re-read",
    contested = "a fit contested in report %s",
}
--- Where a prop's camera factor comes from, in the words the test line prints after "by".
local function FitSource(path)
    local key = path and FileKey(path) or nil
    if key and OwnerFit(key) then return "your saved fit" end
    local st = key and FIT_BY_FILE[key] and FIT_STATUS[key]
    if st then
        local text = (st[1] == "fitted" and STATUS_TEXT[st[3] or ""]) or STATUS_TEXT[st[1]] or (st[1] .. " in report %s")
        return string.format(text, st[2])
    end
    return "an interpolation between measured files, a guess"
end

local function SettleModel(model, x, heightYd, path)
    pcall(function()
        if model.SetPosition then model:SetPosition(x or 0, 0, 0) end
        if model.SetFacing then model:SetFacing(0) end
        local k = CameraDistanceFor(heightYd, path)
        if model.SetCamDistanceScale then
            model:SetCamDistanceScale(k)
            if model.SetModelScale then model:SetModelScale(1) end
        elseif model.SetModelScale then
            model:SetModelScale(1 / k)
        end
        if model.SetAnimation then model:SetAnimation(0) elseif model.SetSequence then model:SetSequence(0) end
    end)
end

local function LoadModel(model, fdid, path, heightYd)
    if not model then return false end
    local winPath = path and path ~= "" and path:gsub("/", "\\") or nil
    local tries = {}
    local idFirst = Cfg("terrainLoader") == "id"
    if idFirst and fdid and fdid > 0 then tries[#tries + 1] = fdid end
    if winPath then tries[#tries + 1] = winPath end
    if not idFirst and fdid and fdid > 0 then tries[#tries + 1] = fdid end
    if winPath then tries[#tries + 1] = (winPath:gsub("%.m2$", ".mdx")) end
    for _, asset in ipairs(tries) do
        local ok = pcall(model.SetModel, model, asset)
        if ok and Loaded(model) then
            SettleModel(model, 0, heightYd, path)
            loadStats.ok = loadStats.ok + 1
            loadStats.lastWin = type(asset) == "number" and ("id " .. asset) or asset
            return true
        end
    end
    loadStats.failed = loadStats.failed + 1
    loadStats.lastFailure = winPath or tostring(fdid)
    return false
end

-- ---------------------------------------------------------------------------
-- Scan and layout
-- ---------------------------------------------------------------------------
local function KeyOf(e) return tostring(e[1]) .. "|" .. e[2] .. "|" .. e[3] .. "|" .. e[4] end

--- Drawable placements within RADIUS of the player across the given tiles, nearest first.
--- View culling happens HERE, before the nearest-N cut, so a prop behind the camera, off-screen
--- or too small never takes a slot from a visible one. Buildings (WMOs) are counted, not listed:
--- a Model frame cannot load them. Models that failed to load wait RETRY_AFTER before a retry.
--- Returns the candidate list and the number of buildings within the radius.
local function Scan(ps, cam, tiles)
    for i = #candidates, 1, -1 do candidates[i] = nil end
    local buildings = 0
    local r2 = RADIUS * RADIUS
    for _, tile in ipairs(tiles) do
        local wmos = tile.wmos or {}
        for i = 1, #wmos do
            local e = wmos[i]
            local dx, dy = e[3] - ps.x, e[4] - ps.y
            if dx * dx + dy * dy <= r2 then buildings = buildings + 1 end
        end
        local list = tile.doodads or {}
        for i = 1, #list do
            local e = list[i]
            local dx, dy = e[3] - ps.x, e[4] - ps.y
            local d2 = dx * dx + dy * dy
            if d2 <= r2 then
                local sx, sy, depth = Math.ProjectPoint(cam, e[3], e[4], e[5])
                if sx and depth >= MIN_DEPTH and sx > -SCREEN_MARGIN and sx < cam.w + SCREEN_MARGIN then
                    local hPx = cam.focal * NominalHeight(e[2]) * e[7] / depth
                    if hPx >= MIN_PX then
                        local key = KeyOf(e)
                        local failed = failedAt[key]
                        if not failed or clock - failed >= RETRY_AFTER then
                            candidates[#candidates + 1] = { e = e, d2 = d2, key = key }
                        end
                    end
                end
            end
        end
    end
    table.sort(candidates, function(a, b) return a.d2 < b.d2 end)
    return candidates, buildings
end

local function Place(model, sx, sy, w, h, dx)
    model:ClearAllPoints()
    model:SetSize(w, h)
    model:SetPoint("BOTTOM", UIParent, "BOTTOMLEFT", sx + dx, sy)
end

local function SetLevel(model, level)
    if model and model.__ematrixLevel ~= level and model.SetFrameLevel then
        model:SetFrameLevel(level)
        model.__ematrixLevel = level
    end
end

-- /fide terrain test: one loaded prop alone at the screen centre over a dimmed world, with the
-- model's position, camera and scale as knobs, so the owner can tell whether a Model frame on this
-- client draws a doodad file at all, and where its view is. Nothing else moves while it is on.
local testMode = nil
local MarkFrame -- defined with EndTest below; ApplyTest calls it
local testHidBox = false
local testFrames = {} -- every /fide terrain test press draws on a brand-new frame, so no earlier knob (a camera index, a scale) can linger on it
-- the client's own question-mark model (the default UI's quest marker): if it shows where a
-- doodad does not, the frame draws and the doodad's own camera or bounds are the question
local KNOWN_MODEL = "interface/buttons/talktomequestionmark.m2"
local lastInfo = { props = 0, buildings = 0, tile = nil, groundZ = nil, pitch = nil }
local ApplyBackdrop -- defined with the enable/disable commands below

--- The pool slot a test press draws: the first loaded one, or the first whose model path holds
--- `pick` (a keyword such as "tree" or "barrel"), so each kind of prop can be sized by eye.
local function TestSlot(pick)
    local first = nil
    for i = 1, MAX_PROPS do
        local s = pool[i]
        if s and s.used and s.entry and s.mono then
            if not pick then return s end
            first = first or s
            if tostring(s.entry[2]):lower():find(pick, 1, true) then return s end
        end
    end
    return first
end

local VARIANT_LABEL = { default = "default (camera distance from the model's height)", cam = "camera", z = "SetPosition x", scale = "model scale", camdist = "camera distance scale", nolight = "no light applied" }
local FRAME_KINDS = { model = "Model", player = "PlayerModel", dressup = "DressUpModel" }

--- A brand-new frame of the asked kind for one test press (falls back to Model), above the pool.
local function NewTestFrame(kind)
    local ok, f = pcall(CreateFrame, kind, nil, overlay)
    if not (ok and f) then ok, f = pcall(CreateFrame, "Model", nil, overlay); kind = "Model" end
    if not (ok and f) then return nil end
    f:SetFrameLevel(LEVEL_MIN + LEVEL_SPAN + 10)
    f:EnableMouse(false)
    testFrames[#testFrames + 1] = f
    return f, kind
end

local function ApplyTest(say)
    local s = TestSlot(testMode.pick)
    if not s then
        say("terrain test: no loaded prop yet (turn the overlay on near placements, wait a second, then try again)")
        return false
    end
    for i = 1, MAX_PROPS do if pool[i] then HideModels(pool[i]) end end
    for _, f in ipairs(testFrames) do f:Hide() end
    local box = _G.FidelityEMatrixFrame
    if box and box:IsShown() then box:Hide(); testHidBox = true end -- the box sits over the screen centre
    local kind = FRAME_KINDS[testMode.frame or ""] or propFrameKind or "PlayerModel"
    local m, actual = NewTestFrame(kind)
    if not m then say("terrain test: the client refused to create a %s frame", kind); return false end
    -- the world overlay's copy of the player stands in the test frame and covered the jar's and the
    -- tree's bases (the ninth report): its copies are hidden while a test frame is up, choice untouched
    if ns.World and ns.World.HideFor then ns.World.HideFor("test", true) end
    if testMode.strata then pcall(m.SetFrameStrata, m, testMode.strata) end
    local fdid, path = s.entry[1], s.entry[2]
    if testMode.known then fdid, path = nil, KNOWN_MODEL end
    local loaded = LoadModel(m, fdid, path, testMode.known and REF_HEIGHT or s.height)
    local which = testMode.known and "the client's own question-mark model (interface/buttons/talktomequestionmark)" or (path:match("([^/]+)$") or path)
    local v, value = testMode.variant or "default", testMode.value
    if v ~= "nolight" and ns.ApplyLight then ns.ApplyLight(m, ns.LIGHTS.mono) end
    pcall(function()
        if v == "cam" and m.SetCamera then m:SetCamera(value or 0)
        elseif v == "z" and m.SetPosition then m:SetPosition(value or 0, 0, 0)
        elseif v == "scale" and m.SetModelScale then m:SetModelScale(value or 1)
        elseif v == "camdist" and m.SetCamDistanceScale then m:SetCamDistanceScale(value or 1) end
    end)
    local fileId, visible, strata, level = "?", "?", "?", "?"
    pcall(function() if m.GetModelFileID then fileId = tostring(m:GetModelFileID()) end end)
    local h = (GetScreenHeight and GetScreenHeight()) or 1080
    local hPx = math.floor(h * 0.4)
    local aspect = testMode.aspect or AspectFor(path)
    m:ClearAllPoints()
    m:SetSize(math.floor(hPx * aspect), hPx)
    m:SetPoint("CENTER", UIParent, "CENTER", 0, 0)
    m:SetAlpha(1.0)
    m:Show()
    MarkFrame(m)
    pcall(function()
        if m.IsVisible then visible = tostring(m:IsVisible()) end
        if m.GetFrameStrata then strata = tostring(m:GetFrameStrata()) end
        if m.GetFrameLevel then level = tostring(m:GetFrameLevel()) end
    end)
    lastInfo.props = 1
    if backdropTex then backdropTex:SetColorTexture(0, 0, 0, 0.6); backdropTex:Show() end
    local knob = (VARIANT_LABEL[v] or v) .. (value ~= nil and (" " .. tostring(value)) or "")
    say("terrain test [%s] on a new %s frame: %s (nominal height %.1f yd, camera x%.2f by %s%s), %s (file id %s), %d px tall and %.2f as wide at the screen centre%s (its edges marked in red, its mid-line thin), strata %s level %s, visible %s; the box and the world's copies are hidden and the world dimmed. Variants: /fide terrain test, camdist <k>, fit <k>|clear (saves the pick's fit for the pool), scale <s>, aspect <a>|auto, pick <word>|any, frame model|player|dressup, strata high, known, cam 0, z 2, nolight; /fide terrain test off restores.",
        knob, actual, which, testMode.known and REF_HEIGHT or (s.height or REF_HEIGHT), CameraDistanceFor(testMode.known and REF_HEIGHT or s.height, path), FitSource(path), testMode.pick and (", picked by \"" .. testMode.pick .. "\"") or "", loaded and "loaded" or "did NOT load", fileId, hPx, aspect, testMode.aspect and " (aspect set for this test)" or "", strata, level, visible)
    return true
end

-- The test frame's edges in red and its mid-line thin, on a frame above the model, so a screenshot
-- shows where the viewport is and where the model sits in it (centred or on its base).
local markFrame, marks = nil, nil
MarkFrame = function(m)
    if not markFrame then
        markFrame = CreateFrame("Frame", nil, overlay)
        markFrame:SetFrameLevel(LEVEL_MIN + LEVEL_SPAN + 20)
        markFrame:EnableMouse(false)
        marks = {}
        for i = 1, 5 do
            local t = markFrame:CreateTexture(nil, "OVERLAY")
            t:SetColorTexture(1, 0.2, 0.2, 0.75)
            marks[i] = t
        end
    end
    markFrame:ClearAllPoints()
    markFrame:SetAllPoints(m)
    local T, B, L, R, C = marks[1], marks[2], marks[3], marks[4], marks[5]
    for _, t in ipairs(marks) do t:ClearAllPoints() end
    T:SetPoint("TOPLEFT", m, "TOPLEFT", 0, 0); T:SetPoint("TOPRIGHT", m, "TOPRIGHT", 0, 0); T:SetHeight(2)
    B:SetPoint("BOTTOMLEFT", m, "BOTTOMLEFT", 0, 0); B:SetPoint("BOTTOMRIGHT", m, "BOTTOMRIGHT", 0, 0); B:SetHeight(2)
    L:SetPoint("TOPLEFT", m, "TOPLEFT", 0, 0); L:SetPoint("BOTTOMLEFT", m, "BOTTOMLEFT", 0, 0); L:SetWidth(2)
    R:SetPoint("TOPRIGHT", m, "TOPRIGHT", 0, 0); R:SetPoint("BOTTOMRIGHT", m, "BOTTOMRIGHT", 0, 0); R:SetWidth(2)
    C:SetPoint("LEFT", m, "LEFT", 0, 0); C:SetPoint("RIGHT", m, "RIGHT", 0, 0); C:SetHeight(1)
    markFrame:Show()
end

local function EndTest()
    testMode = nil
    for _, f in ipairs(testFrames) do f:Hide() end
    if markFrame then markFrame:Hide() end
    if testHidBox and _G.FidelityEMatrixFrame then _G.FidelityEMatrixFrame:Show() end
    testHidBox = false
    if ns.World and ns.World.HideFor then ns.World.HideFor("test", false) end
    ApplyBackdrop()
end

--- Hides what this overlay draws for one screenshot, or shows it again: the report's overlay-off twin.
--- During a terrain test only the test frame and its marks are hidden (the dimmed world stays, so the
--- two shots differ by the model alone); otherwise the overlay's frame. The saved choice
--- (FidelityEMatrix_Config.terrainOverlay) and the enabled state are not touched.
function Terrain.HideForShot(on)
    local hide = on and true or false
    if testMode then
        local f = testFrames[#testFrames]
        if f then if hide then f:Hide() else f:Show() end end
        if markFrame then if hide then markFrame:Hide() else markFrame:Show() end end
    elseif overlay and enabled then
        if hide then overlay:Hide() else overlay:Show() end
    end
end

function Terrain.Layout(cam, eyeX, eyeY, zoom)
    if not overlay then return 0 end
    if testMode then return 1 end
    local anaglyph = Cfg("stereoMode") == "anaglyph"
    local px, delta = Cfg("stereoPixels"), Cfg("stereoDelta")
    local turnSign = Cfg("turnSign")
    local gain = PX_GAIN * (ns.EyeGain and ns.EyeGain() or 1)
    local maxPx = cam.h * MAX_PX_FACTOR
    local drawn = 0
    for i = 1, MAX_PROPS do
        local s = pool[i]
        if s and s.used and s.entry then
            local e = s.entry
            local sx, sy, depth = Math.ProjectPoint(cam, e[3], e[4], e[5])
            local hPx = (depth and depth >= MIN_DEPTH) and (cam.focal * s.height * e[7] / depth) or 0
            if hPx > maxPx then hPx = maxPx end -- a prop right at the camera must not swallow the screen
            if sx and hPx >= MIN_PX and sx > -SCREEN_MARGIN and sx < cam.w + SCREEN_MARGIN then
                local z = Math.DepthFromDistance(depth, zoom)
                local shiftX = Math.ParallaxShift(eyeX, z) * gain
                local shiftY = Math.ParallaxShift(eyeY, z) * gain
                local pair = px * Math.ParallaxShift(1, z) / Math.ParallaxShift(1, STEREO_REF_Z)
                local wPx = hPx * AspectFor(e[2])
                local facing = math.rad(e[6] or 0) - cam.yaw
                -- nearer props draw over farther ones (frames at one level draw in creation order)
                local level = LEVEL_MIN + math.floor(math.max(0, math.min(1, 1 - depth / RADIUS)) * LEVEL_SPAN)
                if anaglyph then
                    if s.mono then s.mono:Hide() end
                    SetLevel(s.left, level); SetLevel(s.right, level)
                    Place(s.left, sx + shiftX, sy + shiftY, wPx, hPx, -pair)
                    Place(s.right, sx + shiftX, sy + shiftY, wPx, hPx, pair)
                    local fl, fr = Math.StereoFacings(facing, turnSign * delta)
                    ns.FaceModel(s.left, fl); ns.FaceModel(s.right, fr)
                    s.left:SetAlpha(1.0); s.right:SetAlpha(Cfg("anaglyphMix"))
                    s.left:Show(); s.right:Show()
                else
                    if s.left then s.left:Hide() end
                    if s.right then s.right:Hide() end
                    SetLevel(s.mono, level)
                    Place(s.mono, sx + shiftX, sy + shiftY, wPx, hPx, 0)
                    ns.FaceModel(s.mono, facing)
                    s.mono:SetAlpha(1.0)
                    s.mono:Show()
                end
                s.drawX, s.drawY, s.drawW, s.drawH = sx + shiftX, sy + shiftY, wPx, hPx -- the frame's bottom centre and size, for the shutter record
                drawn = drawn + 1
            else
                HideModels(s)
            end
        end
    end
    return drawn
end


--- The pose at this moment and every drawable placement's prediction, for the report's shutter: one
--- table, built only when a step's screenshot is taken. It prints nothing, works with the overlay
--- hidden, and measures nothing: the twin shot, read against it, is the reading.
function Terrain.Snapshot()
    local snap = { time = GetTime and GetTime() or 0 }
    local ps = Terrain.PlayerState()
    if not ps then snap.none = "UnitPosition gave nothing"; return snap end
    local own, tiles = Terrain.TilesAround(ps.mapName, ps.x, ps.y)
    local groundZ = Terrain.GroundHeight(own, ps.x, ps.y)
    local cam, pitch = Terrain.BuildCamera(ps, groundZ or 0)
    cam.yaw = ps.facing
    snap.x, snap.y, snap.map, snap.facing, snap.zoom = ps.x, ps.y, ps.mapName, ps.facing, ps.zoom
    snap.tile = own and (ps.mapName .. ":" .. own.col .. ":" .. own.row) or "MISSING"
    snap.ground = groundZ
    snap.pitch, snap.pitchKind = pitch, CameraKind("terrainPitch")
    snap.fovY, snap.fovKind = Cfg("terrainFovY"), CameraKind("terrainFovY")
    snap.focal, snap.w, snap.h = cam.focal, cam.w, cam.h
    if ns.GetEye then snap.eyeX, snap.eyeY = ns.GetEye() end
    snap.overlay = enabled and (testMode and "test" or "on") or "off"
    local slotOf = {}
    for i = 1, MAX_PROPS do
        local s = pool[i]
        if s and s.used and s.key then slotOf[s.key] = s end
    end
    local props = {}
    if #tiles > 0 then
        local found = Scan(ps, cam, tiles)
        for i = 1, math.min(MAX_PROPS, #found) do
            local e, key = found[i].e, found[i].key
            local h = NominalHeight(e[2])
            local fx, fy, depth = Math.ProjectPoint(cam, e[3], e[4], e[5])
            local tx, ty = Math.ProjectPoint(cam, e[3], e[4], e[5] + h * e[7])
            local s = slotOf[key]
            props[#props + 1] = {
                file = FileKey(e[2]), x = e[3], y = e[4], z = e[5], scale = e[7], dist = math.sqrt(found[i].d2), height = h,
                footX = fx, footY = fy, topX = tx, topY = ty, depth = depth,
                k = CameraDistanceFor(h, e[2]), fit = FitSource(e[2]), aspect = AspectFor(e[2]),
                drawn = (s and s.drawH) and { x = s.drawX, y = s.drawY, w = s.drawW, h = s.drawH } or nil,
            }
        end
    end
    snap.props = props
    return snap
end

local function Refresh()
    local ps = Terrain.PlayerState()
    if not ps then return nil end
    local own, tiles = Terrain.TilesAround(ps.mapName, ps.x, ps.y)
    local groundZ = Terrain.GroundHeight(own, ps.x, ps.y) or 0
    local cam, pitch = Terrain.BuildCamera(ps, groundZ)
    cam.yaw = ps.facing
    local found, buildings = Scan(ps, cam, tiles)
    lastInfo.buildings = buildings
    local n = math.min(#found, MAX_PROPS)
    for i = 1, MAX_PROPS do
        local s = GetSlot(i)
        local c = found[i]
        if i <= n and c then
            if s.key ~= c.key then
                local e = c.e
                s.key = c.key
                s.entry = e
                s.height = NominalHeight(e[2])
                if LoadModel(s.mono, e[1], e[2], s.height) then
                    LoadModel(s.left, e[1], e[2], s.height); LoadModel(s.right, e[1], e[2], s.height)
                    s.used = true
                    ns.ApplyLight(s.mono, ns.LIGHTS.mono)
                    ns.ApplyLight(s.left, ns.LIGHTS.red)
                    ns.ApplyLight(s.right, ns.LIGHTS.cyan)
                else
                    -- a failed load frees the slot and hides the previous picture; the model is
                    -- tried again after RETRY_AFTER seconds, so a transient failure does not
                    -- blank that prop for the rest of the session
                    failedAt[c.key] = clock
                    ReleaseSlot(s)
                end
            end
        elseif s.used or s.key then
            ReleaseSlot(s)
        end
    end
    return cam, ps, own, groundZ, pitch
end

local errors = { count = 0, last = nil }
Terrain.errors = errors

local function Step(self, dt)
    if testMode then return end -- the test picture stays put
    clock = clock + dt
    scanAge = scanAge + dt
    if scanAge >= SCAN_INTERVAL or not lastCam then
        scanAge = 0
        local cam, ps, tile, groundZ, pitch = Refresh()
        lastInfo.tile = tile and (tile.map .. ":" .. tile.col .. ":" .. tile.row) or nil
        lastInfo.groundZ, lastInfo.pitch = groundZ, pitch
        if not cam then return end
    else
        -- between scans, track the camera every frame (facing and zoom change continuously)
        local ps = Terrain.PlayerState()
        if ps and lastCam then
            local cam = Terrain.BuildCamera(ps, lastInfo.groundZ or 0)
            cam.yaw = ps.facing
        end
    end
    if lastCam then
        local eyeX, eyeY = ns.GetEye()
        local ps = Terrain.PlayerState()
        lastInfo.props = Terrain.Layout(lastCam, eyeX, eyeY, ps and ps.zoom or 8)
    end
end

local function OnUpdate(self, dt)
    local ok, err = pcall(Step, self, dt)
    if not ok then
        errors.count = errors.count + 1
        errors.last = tostring(err)
        if errors.count >= 3 then
            Terrain.Suspend(errors.last)
            print("|cffff3333[Fidelity EMatrix]|r Terrain overlay stopped after repeated errors (your saved setting is unchanged; /fide terrain on retries): " .. errors.last)
        end
    end
end

-- ---------------------------------------------------------------------------
-- Enable / disable / commands
-- ---------------------------------------------------------------------------
function ApplyBackdrop()
    if not backdropTex then return end
    local mode = Cfg("terrainBackdrop")
    if mode == "black" then backdropTex:SetColorTexture(0, 0, 0, 1); backdropTex:Show()
    elseif mode == "dim" then backdropTex:SetColorTexture(0, 0, 0, 0.6); backdropTex:Show()
    else backdropTex:Hide() end
end

local function Stop()
    if not overlay then return end
    if testMode then EndTest() end
    overlay:SetScript("OnUpdate", nil)
    for i = 1, #pool do ReleaseSlot(pool[i]) end
    lastInfo.props = 0
    overlay:Hide()
end

--- Stops the overlay after errors WITHOUT touching the saved choice, so the next login still
--- starts it and /fide terrain on retries now.
function Terrain.Suspend(reason)
    enabled = false
    suspended = reason or "unknown error"
    Stop()
end

function Terrain.SetEnabled(on)
    enabled = on and true or false
    suspended = nil
    FidelityEMatrix_Config.terrainOverlay = enabled
    if enabled then
        errors.count = 0
        if not overlay then
            overlay = CreateFrame("Frame", "FidelityEMatrix_TerrainOverlay", UIParent)
            overlay:SetAllPoints(UIParent)
            overlay:SetFrameStrata("BACKGROUND")
            overlay:SetFrameLevel(0)
            overlay:EnableMouse(false)
            backdropTex = overlay:CreateTexture(nil, "BACKGROUND", nil, -8)
            backdropTex:SetAllPoints(overlay)
            backdropTex:Hide()
        end
        ApplyBackdrop()
        overlay:Show()
        overlay:SetScript("OnUpdate", OnUpdate)
        scanAge = SCAN_INTERVAL
        lastCam = nil
    else
        Stop()
    end
end

function Terrain.IsEnabled() return enabled end
function Terrain.IsSuspended() return suspended end
function Terrain.Info() return lastInfo end

local USAGE = "Usage: /fide terrain <on|off|status|probe|test [off|camdist <k>|fit <k|clear>|scale <s>|aspect <a|auto>|pick <word|any>|frame <model|player|dressup>|strata <background|medium|high>|known|own|cam <n>|z <x>|nolight]|loader <path|id>|fov <deg>|pitch <deg>|backdrop <none|dim|black>>"

function Terrain.Command(args, say)
    local sub = args[2] or "toggle"
    local v = tonumber(args[3])
    if sub == "on" then Terrain.SetEnabled(true)
    elseif sub == "off" then Terrain.SetEnabled(false)
    elseif sub == "toggle" then Terrain.SetEnabled(not enabled)
    elseif sub == "fov" and v then FidelityEMatrix_Config.terrainFovY = math.rad(math.min(math.max(v, 20), 150)); say("Vertical field of view: %.0f degrees", v); return
    elseif sub == "pitch" and v then FidelityEMatrix_Config.terrainPitch = math.rad(math.min(math.max(v, 3), 80)); say("Camera pitch fixed at %.0f degrees (the client gives no pitch to read)", v); return
    elseif sub == "loader" and (args[3] == "path" or args[3] == "id") then FidelityEMatrix_Config.terrainLoader = args[3]; say("Model loader tries the %s first (restart the overlay to reload)", args[3]); return
    elseif sub == "probe" then
        -- everything the laptop needs to say why nothing is drawn
        local ps = Terrain.PlayerState()
        if not ps then say("probe: UnitPosition gave nothing (instance, or the API is restricted here)"); return end
        local own, tiles, col, row = Terrain.TilesAround(ps.mapName, ps.x, ps.y)
        local groundZ = Terrain.GroundHeight(own, ps.x, ps.y)
        say("probe: pos %.1f, %.1f (%s) facing %.2f zoom %.1f | tile %s:%d:%d %s, %d tile(s) around | ground %s",
            ps.x, ps.y, ps.mapName, ps.facing, ps.zoom, ps.mapName, col, row, own and "FOUND" or "MISSING in " .. Terrain.BuildLabel(), #tiles,
            groundZ and string.format("%.1f", groundZ) or "nil")
        if #tiles == 0 then return end
        local cam, pitch = Terrain.BuildCamera(ps, groundZ or 0)
        cam.yaw = ps.facing
        local found, buildings = Scan(ps, cam, tiles)
        say("probe: %d drawable placements within %d yd (%d buildings not drawn: Model frames load M2 only); camera pitch %.1f deg %s, focal %.0f px %s, screen %dx%d",
            #found, RADIUS, buildings, math.deg(pitch), CameraKind("terrainPitch"), cam.focal, CameraKind("terrainFovY"), cam.w, cam.h)
        for i = 1, math.min(MAX_PROPS, #found) do
            local e = found[i].e
            local sx, sy, depth = Math.ProjectPoint(cam, e[3], e[4], e[5])
            local hPx = depth and (cam.focal * NominalHeight(e[2]) * e[7] / depth) or 0
            say("  %d. %s at %.1f,%.1f,%.1f dist %.1f -> %s", i, (e[2]:match("([^/]+)$") or e[2]), e[3], e[4], e[5], math.sqrt(found[i].d2),
                sx and string.format("screen %.0f,%.0f depth %.1f height %.0f px", sx, sy, depth, math.min(hPx, cam.h * MAX_PX_FACTOR)) or "behind the camera")
        end
        say("probe: models loaded %d, failed %d%s%s", loadStats.ok, loadStats.failed,
            loadStats.lastWin and (", last loaded via " .. loadStats.lastWin) or "", loadStats.lastFailure and (", last failure " .. loadStats.lastFailure) or "")
        return
    elseif sub == "test" then
        local what, n = args[3], tonumber(args[4])
        if what == "off" then
            if testMode then EndTest(); say("terrain test off: the overlay draws as before") else say("terrain test is not on") end
            return
        end
        if not enabled then say("terrain test needs the overlay on: /fide terrain on, stand near placements, then /fide terrain test"); return end
        local prev = testMode or {}
        testMode = { variant = "default", value = nil, known = prev.known or false, frame = prev.frame, strata = prev.strata, pick = prev.pick, aspect = prev.aspect }
        if what == "cam" and n then testMode.variant, testMode.value = "cam", math.floor(n)
        elseif what == "z" and n then testMode.variant, testMode.value = "z", math.min(math.max(n, -50), 50)
        elseif what == "scale" and n and n > 0 then testMode.variant, testMode.value = "scale", math.min(n, 50)
        elseif what == "camdist" and n and n > 0 then testMode.variant, testMode.value = "camdist", math.min(n, 50)
        elseif what == "fit" and (args[4] == "clear" or (n and n > 0)) then
            local s = TestSlot(testMode.pick)
            if not s then say("terrain test fit: no prop picked yet"); return end
            local key = FileKey(s.entry[2])
            FidelityEMatrix_Config.propFit = FidelityEMatrix_Config.propFit or {}
            if args[4] == "clear" then FidelityEMatrix_Config.propFit[key] = nil
            else FidelityEMatrix_Config.propFit[key] = math.min(math.max(n, 0.25), 16.0) end
            say("terrain test fit: %s now uses camera x%.2f (%s); the pool's copies are re-settled", key, CameraDistanceFor(s.height, s.entry[2]), FitSource(s.entry[2]))
            for i = 1, MAX_PROPS do
                local q = pool[i]
                if q and q.used and q.entry and FileKey(q.entry[2]) == key then
                    SettleModel(q.mono, 0, q.height, q.entry[2]); SettleModel(q.left, 0, q.height, q.entry[2]); SettleModel(q.right, 0, q.height, q.entry[2])
                end
            end
            testMode.variant, testMode.value = "default", nil
        elseif what == "nolight" then testMode.variant = "nolight"
        elseif what == "known" then testMode.known = true
        elseif what == "own" then testMode.known = false
        elseif what == "pick" and args[4] then
            if args[4] == "any" then testMode.pick = nil else testMode.pick = args[4]:lower() end
        elseif what == "frame" and FRAME_KINDS[args[4] or ""] then testMode.frame = args[4]
        elseif what == "aspect" and (args[4] == "auto" or (n and n > 0)) then
            if args[4] == "auto" then testMode.aspect = nil else testMode.aspect = math.min(math.max(n, 0.2), 4.0) end
        elseif what == "strata" and (args[4] == "background" or args[4] == "medium" or args[4] == "high") then
            if args[4] == "background" then testMode.strata = nil else testMode.strata = args[4]:upper() end
        elseif what and what ~= "default" then say(USAGE); return end
        if not TestSlot(testMode.pick) then Refresh() end -- the overlay may have come on this very frame: scan now
        if not ApplyTest(say) then testMode = nil end
        return
    elseif sub == "backdrop" and (args[3] == "none" or args[3] == "dim" or args[3] == "black") then FidelityEMatrix_Config.terrainBackdrop = args[3]; ApplyBackdrop(); say("Terrain backdrop: %s", args[3]); return
    elseif sub == "status" then
        local ps = Terrain.PlayerState()
        say("Terrain overlay: %s | client %s | frames %s | tile %s | ground %s | pitch %s | props drawn %d | buildings nearby %d (not drawn) | models loaded %d failed %d | errors %d%s | pos %s",
            enabled and "ON" or (suspended and ("SUSPENDED after errors: " .. suspended) or "off"), Terrain.BuildLabel(), tostring(propFrameKind or "none yet"), tostring(lastInfo.tile),
            lastInfo.groundZ and string.format("%.1f", lastInfo.groundZ) or "?",
            lastInfo.pitch and string.format("%.1f deg %s", math.deg(lastInfo.pitch), CameraKind("terrainPitch")) or "?", lastInfo.props or 0, lastInfo.buildings or 0, loadStats.ok, loadStats.failed,
            errors.count, errors.last and (" (last: " .. errors.last .. ")") or "",
            ps and string.format("%.1f, %.1f (%s)", ps.x, ps.y, ps.mapName) or "unknown (no UnitPosition here)")
        return
    else
        say(USAGE)
        return
    end
    say("Terrain overlay %s: map placements near you drawn as depth props (client %s).", enabled and "ON" or "OFF", Terrain.BuildLabel())
end

-- Test / dump access
Terrain._pool = pool
Terrain._lastCam = function() return lastCam end
Terrain._failedAt = failedAt
Terrain._testFrames = testFrames
Terrain.FrameKind = function() return propFrameKind end
Terrain.CameraDistanceFor = CameraDistanceFor
Terrain.FileKey = FileKey
Terrain.AspectFor = AspectFor
Terrain._markFrame = function() return markFrame end
Terrain.RETRY_AFTER = RETRY_AFTER
Terrain.FitSource = FitSource
Terrain.CameraKind = CameraKind
Terrain.DEFAULTS = DEFAULTS
